+    let sbl = std::fs::read_to_string(out.join("LOWER20.SBL")).unwrap();
+    for field in [
+        "ID_PUNCH,c_left,",
+        "ID_SEPCUT,\"0.0\",",
+        "ID_EXITMODE,c_entper,",
+        "ID_STPENTRY,\"stp1\",",
+        "ID_STPOPEN,c_work,",
+        "ID_STPEXIT,\"stp2\",",
+        "ID_STPOPEX,c_work,",
+        "\"stp1\",ID_POSX,\"-44.000\",",
+        "\"stp1\",ID_POSY,\"-3.000\",",
+        "\"stp2\",ID_POSX,\"44.000\",",
+        "\"stp2\",ID_POSY,\"-3.000\",",
